@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@CurrentWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @AlertCardClass">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text">
                    <span class="fs-1 fw-bold">@AlertService.CurrentAlertCount</span>
                    <span class="ms-2">items below minimum level</span>
                </p>
                <p class="text-muted mb-0">
                    <small>Auto-refreshes every 10 seconds</small>
                </p>
            </div>
        </div>
    </div>
</div>

<div class="row mt-4">
    <div class="col-12">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Alert History</h5>
                <p class="text-muted">Polling is @(_isPolling ? "active" : "inactive") for this page.</p>
                @if (_alertLog.Count > 0)
                {
                    <ul class="list-group list-group-flush" style="max-height: 200px; overflow-y: auto;">
                        @foreach (var entry in _alertLog.AsEnumerable().Reverse().Take(10))
                        {
                            <li class="list-group-item">@entry</li>
                        }
                    </ul>
                }
                else
                {
                    <p class="mb-0">Waiting for first poll…</p>
                }
            </div>
        </div>
    </div>
</div>

@code {
    private bool _isPolling;
    private readonly List<string> _alertLog = new();

    private string CurrentWarehouseName =>
        Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId)?.Name
        ?? "Unknown";

    private string AlertCardClass =>
        AlertService.CurrentAlertCount > 10 ? "border-danger" :
        AlertService.CurrentAlertCount > 5 ? "border-warning" : "border-success";

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        AlertService.StartPolling();
        _isPolling = true;
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void HandleAlertChanged()
    {
        _alertLog.Add($"[{DateTime.Now:HH:mm:ss}] {WarehouseState.CurrentWarehouseId}: {AlertService.CurrentAlertCount} low-stock items");
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        AlertService.StopPolling();
        _isPolling = false;
    }
}

